  $('#industry-general-extra').replaceChildren(row('지형',TERRAIN_TYPES[cell.geology.terrain.terrainType]??'미확인'),row('실제 면적',fmt(slots.areaKm2)+' km²'),row('인구',cell.scenario.populationPersons===null?'미설정':fmt(cell.scenario.populationPersons)+'명'),row('기반시설',cell.scenario.infrastructureLevel===null?'미설정':String(cell.scenario.infrastructureLevel)),row('환경', '문명별 확인 자료 미연결'),row('광업 접근',s.fixture?'개발 조사 장비 · 원천 별도 확인':'잠정: 발견 단계 ≤1 · 상대 깊이 ≤25'));
